import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';
import {register} from 'node:module';register(new URL('./helpers/ts-import-hooks.mjs',import.meta.url));
const {createPlayerWorlds}=await import('../electron/main/player-worlds.ts');
function fixture(){const directory=fs.mkdtempSync(path.join(os.tmpdir(),'cw-slots-')),s={worlds:[],activeWorldId:null,created:[],navigated:[],retries:[],cancelled:[],failSwitch:false};
 const deps={directory,list:async()=>structuredClone({worlds:s.worlds,activeWorldId:s.activeWorldId}),changed:()=>{},
 navigate:async r=>{s.navigated.push(r);if(r.operation==='create'){let row=s.worlds.find(w=>w.operationId===r.operationId);if(!row){row={id:'world-'+(s.worlds.length+1),title:r.title,runtimeKind:r.baseId==='creation-sandbox'?'godot':'legacy',baseId:r.baseId,state:r.baseId==='creation-sandbox'?'initializing':'ready',operationId:r.operationId};s.worlds.push(row);s.created.push(row.id);}s.activeWorldId=row.id;if(s.loseCreate){s.loseCreate=false;throw Error('LOST_ACK');}return row;}
 if(s.failSwitch)throw Error('SAVE_FAILED');s.activeWorldId=r.id;return {ok:true,activeWorldId:r.id};},
 retry:async id=>{s.retries.push(id);s.worlds.find(w=>w.id===id).state='initializing';},
 cancel:async id=>{s.cancelled.push(id);Object.assign(s.worlds.find(w=>w.id===id),{state:'failed',creation:{actions:['retry']}});}};
 return {s,deps,api:createPlayerWorlds(deps)};}
test('reads do not create; each kind owns one durable world over repeated entry and restart',async()=>{const {s,deps,api}=fixture();assert.equal((await api.read()).slots.length,2);assert.equal(s.created.length,0);
 const web=await api.enter({kind:'web'}),godot=await api.enter({kind:'godot'});assert.equal(web.state,'ready');assert.equal(godot.state,'initializing');
 s.worlds.find(w=>w.id===godot.worldId).state='ready';const reboot=createPlayerWorlds(deps);await reboot.enter({kind:'web'});await reboot.enter({kind:'godot'});assert.equal(s.created.length,2);assert.equal(s.activeWorldId,godot.worldId);});
test('lost create acknowledgement reuses the same operation without a duplicate',async()=>{const {s,deps,api}=fixture();s.loseCreate=true;await assert.rejects(api.enter({kind:'web'}),/LOST_ACK/);const result=await createPlayerWorlds(deps).enter({kind:'web'});assert.equal(result.worldId,s.created[0]);assert.equal(s.created.length,1);});
test('retain explicit current and sole compatible worlds, never reinterpret other Godot bases',async()=>{const {s,api}=fixture();s.worlds=[{id:'g1',runtimeKind:'godot',baseId:'creation-sandbox',state:'ready'},{id:'g2',runtimeKind:'godot',baseId:'creation-sandbox',state:'ready'},{id:'old',runtimeKind:'godot',baseId:'side-view',state:'ready'},{id:'w',runtimeKind:'legacy',state:'ready'}];
 s.activeWorldId='old';let result=await api.read();assert.equal(result.activeKind,null);assert.equal(result.slots[0].worldId,null);assert.equal(result.slots[1].worldId,'w');
 s.activeWorldId='g2';await api.remember('g2');s.activeWorldId='w';result=await api.read();assert.equal(result.slots[0].worldId,'g2');assert.equal(s.created.length,0);});
test('failed saved world retries its original initializer and cancellation returns to origin',async()=>{const {s,api}=fixture();const web=await api.enter({kind:'web'}),godot=await api.enter({kind:'godot'});await api.cancel({kind:'godot'});assert.equal(s.activeWorldId,web.worldId);assert.deepEqual(s.cancelled,[godot.worldId]);const retry=await api.enter({kind:'godot'});assert.equal(retry.worldId,godot.worldId);assert.equal(retry.state,'initializing');assert.deepEqual(s.retries,[godot.worldId]);assert.equal(s.created.length,2);});
test('save rejection cannot report entry success or overwrite the old world',async()=>{const {s,api}=fixture();const web=await api.enter({kind:'web'}),godot=await api.enter({kind:'godot'});s.worlds.find(w=>w.id===godot.worldId).state='ready';s.failSwitch=true;await assert.rejects(api.enter({kind:'web'}),/SAVE_FAILED/);assert.equal(s.activeWorldId,godot.worldId);s.failSwitch=false;assert.equal((await api.enter({kind:'web'})).worldId,web.worldId);});
test('missing pinned world or corrupt index requires recovery rather than silent replacement',async()=>{const {s,deps,api}=fixture();await api.enter({kind:'web'});s.worlds=[];await assert.rejects(api.enter({kind:'web'}),/PLAYER_WORLD_UNAVAILABLE/);assert.equal(s.created.length,1);
 fs.writeFileSync(path.join(deps.directory,'player-worlds.json'),'{broken');await assert.rejects(api.read());assert.equal(s.created.length,1);});
test('overlapping entries share only the same kind and reject foreign input',async()=>{const {deps,api}=fixture();let release;const original=deps.navigate;deps.navigate=async r=>{await new Promise(resolve=>release=resolve);return original(r);};const first=api.enter({kind:'web'});assert.equal(api.enter({kind:'web'}),first);await assert.rejects(api.enter({kind:'godot'}),/WORLD_BUSY/);await assert.rejects(api.enter({kind:'web',worldId:'foreign'}),/INVALID/);while(!release)await new Promise(r=>setImmediate(r));release();deps.navigate=original;await first;});

test('returning to an initializing Godot world selects it so first load can continue',async()=>{const {s,api}=fixture();const godot=await api.enter({kind:'godot'}),web=await api.enter({kind:'web'});assert.equal(s.activeWorldId,web.worldId);const resumed=await api.enter({kind:'godot'});assert.equal(resumed.state,'initializing');assert.equal(s.activeWorldId,godot.worldId);await api.cancel({kind:'godot'});assert.equal(s.activeWorldId,web.worldId);assert.equal(s.created.length,2);});

test('cancellation holds the operation lock and cannot overwrite external navigation',async()=>{const {s,deps,api}=fixture();await api.enter({kind:'web'});const godot=await api.enter({kind:'godot'});let release;const original=deps.cancel;deps.cancel=async id=>{await new Promise(resolve=>release=resolve);return original(id);};const cancellation=api.cancel({kind:'godot'});await assert.rejects(api.enter({kind:'godot'}),/WORLD_BUSY/);await assert.rejects(api.enter({kind:'web'}),/WORLD_BUSY/);await assert.rejects(api.cancel({kind:'godot'}),/WORLD_BUSY/);while(!release)await new Promise(r=>setImmediate(r));s.worlds.push({id:'archive',runtimeKind:'legacy',state:'ready'});s.activeWorldId='archive';release();await assert.rejects(cancellation,/PLAYER_WORLD_CHANGED/);assert.equal(s.activeWorldId,'archive');assert.deepEqual(s.cancelled,[godot.worldId]);});

test('slot inspection excludes unrelated archives and one status outage does not block the other engine',async()=>{const {s,deps,api}=fixture();const web=await api.enter({kind:'web'}),godot=await api.enter({kind:'godot'});s.worlds.push({id:'unrelated',runtimeKind:'godot',baseId:'side-view',state:'initializing'});const inspected=[];deps.inspect=async row=>{inspected.push(row.id);if(row.id===godot.worldId)throw Error('STATUS_OUTAGE');return row;};const current=await api.read();assert.deepEqual(inspected.sort(),[web.worldId,godot.worldId].sort());assert.equal(current.slots[0].state,'failed');assert.equal(current.slots[1].state,'ready');await assert.rejects(api.enter({kind:'godot'}),/STATUS_OUTAGE/);assert.equal((await api.enter({kind:'web'})).state,'ready');});
